?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(STORE_NAME)?></title><meta name="description" content="Loja online JADIEL SHOP"><style>
