splay:grid;place-items:center;position:relative;overflow:hidden}.orb{width:240px;height:240px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#9fffd0,#25e58a 22%,#0b8050 55%,#06130e 72%);box-shadow:0 0 80px #25e58a55;animation:float 5s ease-in-out infinite}.ring{position:absolute;width:310px;height:310px;border:1px solid #25e58a40;border-radius:50%;animation:spin 14s linear infinite}@keyframes float{50%{transform:translateY(-12px)}}@keyframes spin{to{transform:rotate(360deg)}}main{max-width:1180px;margin:auto;padding:10px 20px 90px}.toolbar{display:flex;gap:10px;align-items:center;margin:20px 0;flex-wrap:wrap}.search{flex:1;min-width:220px;background:#ffffff08;border:1px solid var(--line);color:var(--text);padding:13px 15px;border-radius:14px;outline:none}.search:focus{border-color:#25e58a88}.chips{display:flex;gap:7px;overflow:auto}.chip{border:1px solid var(--line);background:#ffffff06;color:var(--muted);padding:10px 13px;border-radius:999px;white-space:nowrap}.chip.active{background:#25e58a18;color:var(--green);border-color:#25e58a55}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.product{background:linear-gradient(180deg,#ffffff07,#ffffff03);border:1px solid var(--line);border-radius:20px;overflow:hidden;transition:.25s;position:relative}.product:hover{transform:translateY(-5px);border-color:#25e58a55;box-shadow:0 18px 50px #0005}.pic{aspect-ratio:1/1;background:#0a1511;overflow:hidden}.pic img{width:100%;height:100%;object-fit:cover;display:block;transition:.5s}.product:hover .pic img{transform:scale(1.05)}.info{padding:15px}.cat{font-size:11px;color:var(--green);text-transform:uppercase;font-weight:800;letter-spacing:1px}.info h3{margin:7px 0;font-size:16px}.price{font-size:21px;font-weight:900}.old{font-size:12px;color:#70857b;text-decoration:line-through;margin-left:6px}.buy{width:100%;border:0;background:#25e58a;color:#03160d;font-weight:900;padding:11px;border-radius:12px;margin-top:13px}.drawer,.modal{position:fixed;inset:0;z-index:50;display:none;background:#0009;backdrop-filter:blur(8px)}.drawer.open,.modal.open{display:block}.panel{position:absolute;right:0;top:0;height:100%;width:min(440px,94vw);background:#09130f;border-left:1px solid var(--line);padding:22px;overflow:auto;box-shadow:var(--shadow)}.modal .box{width:min(560px,94vw);max-height:90vh;overflow:auto;margin:5vh auto;background:#0b1712;border:1px solid var(--line);border-radius:24px;padding:22px;box-shadow:var(--shadow)}.row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid #ffffff0a}.row img{width:55px;height:55px;border-radius:12px;object-fit:cover}.qty{display:flex;align-items:center;gap:8px}.qty button{width:30px;height:30px;border:1px solid var(--line);background:#ffffff08;color:white;border-radius:9px}.field{display:grid;gap:7px;margin:11px 0}.field input,.field textarea,.field select{width:100%;background:#ffffff07;border:1px solid var(--line);color:white;padding:12px;border-radius:12px;outline:none}.close{border:1px solid var(--line);background:#ffffff07;color:white;border-radius:10px;padding:8px 11px}.total{font-size:23px;font-weight:900;padding:18px 0}.empty{text-align:center;padding:55px;color:var(--muted);border:1px dashed var(--line);border-radius:20px}.toast{position:fixed;z-index:80;bottom:22px;left:50%;transform:translate(-50%,20px);opacity:0;background:#eafff4;color:#052016;padding:12px 17px;border-radius:13px;font-weight:800;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}footer{border-top:1px solid var(--line);padding:30px 20px;color:var(--muted);text-align:center}@media(max-width:900px){.hero{grid-template-columns:1fr}.showcase{min-height:250px}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.nav{height:62px}.navlinks{display:none}.hero{padding-top:45px}.hero h1{letter-spacing:-2.5px}.grid{grid-template-columns:repeat(2,1fr);gap:10px}.info{padding:11px}.info h3{font-size:14px}.price{font-size:18px}.orb{width:180px;height:180px}.ring{width:230px;height:230px}}
</style></head><body><header class="top"><nav class="nav"><div class="brand">JADIEL <b>SHOP</b></div><div class="navlinks"><button onclick="scrollTo(0,0)">Início</button><button onclick="document.querySelector('#produtos').scrollIntoView({behavior:'smooth'})">Produtos</button><button onclick="openModal('sobre')">Como funciona</button></div><div class="actions"><button class="icon" onclick="openModal('login')">👤</button><button class="icon cart" onclick="openCart()">🛒<span class="badge" id="count">0</span></button></div></nav></header><section class="hero"><div><div class="eyebrow">Compra simples • Envio pelo fornecedor</div><h1>Produtos que chegam até você.</h1><p>Uma experiência de compra moderna. Você escolhe, paga e acompanha o pedido; o fornecedor parceiro cuida da separação e do envio.</p><button class="cta" onclick="document.querySelector('#produtos').scrollIntoView({behavior:'smooth'})">Explorar produtos →</button></div><div class="showcase"><div class="ring"></div><div class="orb"></div></div></section><main id="produtos"><div class="toolbar"><input id="search" class="search" placeholder="Buscar produtos..." oninput="render()"><div class="chips" id="chips"></div></div><div id="grid" class="grid"></div></main><footer>© <?=date('Y')?> <?=e(STORE_NAME)?> · Compra segura · Atendimento online</footer><div id="drawer" class="drawer" onclick="if(event.target===this)closeCart()"><aside class="panel"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Seu carrinho</h2><button class="close" onclick="closeCart()">Fechar</button></div><div id="cartItems"></div><div class="total" id="cartTotal">R$ 0,00</div><button class="buy" onclick="checkout()">Finalizar compra</button></aside></div><div id="modal" class="modal" onclick="if(event.target===this)closeModal()"><div class="box" id="modalBox"></div></div><div id="toast" class="toast"></div><script>
const products=<?=json_encode($products,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let cart=JSON.parse(localStorage.getItem('jadiel_cart')||'{}');
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);function e(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function save(){localStorage.setItem('jadiel_cart',JSON.stringify(cart));updateCount()}function updateCount(){document.querySelector('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}function add(id){cart[id]=(cart[id]||0)+1;save();toast('Produto adicionado ao carrinho');openCart()}function remove(id){delete cart[id];save();renderCart()}function change(id,d){cart[id]=Math.max(0,(cart[id]||0)+d);if(!cart[id])delete cart[id];save();renderCart()}function openCart(){document.querySelector('#drawer').classList.add('open');renderCart()}function closeCart(){document.querySelector('#drawer').classList.remove('open')}
function renderCart(){let el=document.querySelector('#cartItems'),items=Object.entries(cart).map(([id,q])=>({p:products.find(x=>x.id===id),q})).filter(x=>x.p);if(!items.length){el.innerHTML='<div class="empty">Seu carrinho está vazio.</div>';document.querySelector('#cartTotal').textContent=money(0);return}el.innerHTML=items.map(({p,q})=>`<div class="row"><img src="${e(p.image)}"><div style="flex:1"><b>${e(p.name)}</b><div>${money(p.price)} · ${q} un.</div></div><div class="qty"><button onclick="change('${p.id}',-1)">−</button><b>${q}</b><button onclick="change('${p.id}',1)">+</button></div><button class="close" onclick="remove('${p.id}')">×</button></div>`).join('');let total=items.reduce((s,x)=>s+x.p.price*x.q,0);document.querySelector('#cartTotal').textContent=money(total)}
function checkout(){if(!Object.keys(cart).length)return toast('Adicione um produto primeiro');openModal('checkout')}
function openModal(type){let box=document.querySelector('#modalBox');if(type==='login')box.innerHTML='<button class="close" style="float:right" onclick="closeModal()">×</button><h2>Área do cliente</h2><p style="color:var(--muted)">O acompanhamento do pedido será vinculado ao e-mail informado na compra.</p><div class="field"><label>E-mail</label><input id="loginEmail" type="email" placeholder="voce@email.com"></div><button class="buy" onclick="toast(\'Use seu e-mail para acompanhar os pedidos após finalizar uma compra.\');closeModal()">Continuar</button>';if(type==='sobre')box.innerHTML='<button class="close" style="float:right" onclick="closeModal()">×</button><h2>Como funciona?</h2><p style="color:var(--muted);line-height:1.7">Você compra normalmente pela loja. Depois da confirmação do pagamento, o pedido aparece no painel do gestor para encaminhamento ao fornecedor. O fornecedor parceiro faz a separação e envia diretamente ao cliente. A loja não mantém estoque próprio.</p>';if(type==='checkout')box.innerHTML='<button class="close" style="float:right" onclick="closeModal()">×</button><h2>Finalizar pedido</h2><div class="field"><label>Nome completo</label><input id="buyerName"></div><div class="field"><label>E-mail</label><input id="buyerEmail" type="email"></div><div class="field"><label>WhatsApp</label><input id="buyerPhone" placeholder="(00) 00000-0000"></div><div class="field"><label>Endereço para entrega</label><textarea id="buyerAddress" rows="3" placeholder="Rua, número, bairro, cidade - UF, CEP"></textarea></div><button class="buy" onclick="placeOrder()">Criar pedido</button>';document.querySelector('#modal').classList.add('open')}function closeModal(){document.querySelector('#modal').classList.remove('open')}
async function placeOrder(){let name=document.querySelector('#buyerName').value.trim(),email=document.querySelector('#buyerEmail').value.trim(),phone=document.querySelector('#buyerPhone').value.trim(),address=document.querySelector('#buyerAddress').value.trim();if(!name||!email||!phone||!address)return toast('Preencha todos os dados');let items=Object.entries(cart).map(([id,q])=>({id,qty:q}));let r=await fetch('api.php?action=order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,email,phone,address,items})});let j=await r.json();if(!j.ok)return toast(j.error||'Não foi possível criar o pedido');cart={};save();closeModal();closeCart();openModal('success');document.querySelector('#modalBox').innerHTML=`<h2>Pedido criado 🎉</h2><p style="color:var(--muted)">Número do pedido: <b>${e(j.order_id)}</b></p><p style="color:var(--muted)">${e(j.message)}</p><button class="buy" onclick="closeModal()">Continuar comprando</button>`}
function render(){let q=document.querySelector('#search').value.toLowerCase(),cat=document.querySelector('.chip.active')?.dataset.cat||'';let list=products.filter(p=>(!q||p.name.toLowerCase().includes(q))&&(!cat||p.category===cat));document.querySelector('#grid').innerHTML=list.length?list.map(p=>`<article class="product"><div class="pic"><img loading="lazy" src="${e(p.image)}" alt="${e(p.name)}"></div><div class="info"><div class="cat">${e(p.category)}</div><h3>${e(p.name)}</h3><div class="price">${money(p.price)} ${p.old_price?`<span class="old">${money(p.old_price)}</span>`:''}</div><button class="buy" onclick="add('${p.id}')">Adicionar ao carrinho</button></div></article>`).join(''):'<div class="empty" style="grid-column:1/-1">Nenhum produto encontrado.</div>'}
function renderChips(){let cats=['Todos',...<?=json_encode($categories,JSON_UNESCAPED_UNICODE)?>];document.querySelector('#chips').innerHTML=cats.map((c,i)=>`<button class="chip ${i===0?'active':''}" data-cat="${i?'${e(c)}':''}" onclick="document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));this.classList.add('active');render()">${e(c)}</button>`).join('')}function toast(t){let x=document.querySelector('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2500)}renderChips();render();updateCount();
</script></body></html>